{"implementation": "def solve(case):
    payload = case.get("payload")
    if not isinstance(payload, dict):
        raise ValueError("payload missing or invalid")
    segments = payload.get("segments")
    budget = payload.get("budget")
    if not isinstance(segments, list) or not isinstance(budget, int):
        raise ValueError("segments or budget invalid")
    for seg in segments:
        if not all(k in seg for k in ("name","importance","minimum","capacity")):
            raise ValueError("segment missing fields")
        if not isinstance(seg["name"], str) or not isinstance(seg["importance"], int) or not isinstance(seg["minimum"], int) or not isinstance(seg["capacity"], int):
            raise ValueError("segment field types invalid")
    sum_min = sum(seg["minimum"] for seg in segments)
    sum_cap = sum(seg["capacity"] for seg in segments)
    if budget < sum_min:
        raise ValueError("budget below minimum sum")
    if budget > sum_cap:
        raise ValueError("budget exceeds total capacity")
    n = len(segments)
    alloc = [seg["minimum"] for seg in segments]
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i, seg in enumerate(segments):
            ratio = seg["importance"] / (alloc[i] + 1)
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        alloc[best_idx] += 1
        remaining -= 1
    allocations = {segments[i]["name"]: alloc[i] for i in range(n)}
    name_mapping = [segments[i]["name"] for i in range(n)]
    total = sum(alloc)
    return {"allocations": allocations, "name_mapping": name_mapping, "total": total}"}
